package com.mobileapi.service

import kotlinx.coroutines.*
import javax.xml.parsers.DocumentBuilderFactory
import javax.xml.parsers.SAXParserFactory
import org.xml.sax.InputSource
import org.xml.sax.helpers.DefaultHandler
import org.xml.sax.Attributes
import java.io.StringReader
import java.util.concurrent.ConcurrentHashMap
import java.security.MessageDigest
import java.security.SecureRandom

// Configuration registry that accumulates parser settings from multiple sources
object ParserConfigRegistry {
    private val features = ConcurrentHashMap<String, Boolean>()
    private val properties = ConcurrentHashMap<String, Any>()
    private var initialized = false

    fun registerFeature(uri: String, value: Boolean) {
        features[uri] = value
    }

    fun registerProperty(name: String, value: Any) {
        properties[name] = value
    }

    fun getFeatures(): Map<String, Boolean> = features.toMap()
    fun getProperties(): Map<String, Any> = properties.toMap()

    suspend fun initializeDefaults() {
        if (initialized) return
        withContext(Dispatchers.Default) {
            // Security hardening: disable external entities
            registerFeature("http://apache.org/xml/features/disallow-doctype-decl", true)
            registerFeature("http://xml.org/sax/features/external-general-entities", false)
            registerFeature("http://xml.org/sax/features/external-parameter-entities", false)
            registerFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false)
            initialized = true
        }
    }

    fun reset() {
        features.clear()
        properties.clear()
        initialized = false
    }
}

// Middleware that applies security policies based on content type
class SecurityPolicyMiddleware {
    private val trustedOrigins = setOf("internal-service", "admin-panel")

    suspend fun applyPolicy(origin: String?, contentType: String): ParserMode {
        return withContext(Dispatchers.IO) {
            when {
                origin in trustedOrigins && contentType == "application/xml" -> ParserMode.TRUSTED
                contentType == "application/xml" -> ParserMode.RESTRICTED
                else -> ParserMode.REJECT
            }
        }
    }
}

enum class ParserMode { TRUSTED, RESTRICTED, REJECT }

// The XML parsing service that processes mobile API requests
class XmlProcessingService {
    private val middleware = SecurityPolicyMiddleware()

    suspend fun processRequest(xmlBody: String, origin: String?, contentType: String): Result<Map<String, String>> {
        return withContext(Dispatchers.IO) {
            val mode = middleware.applyPolicy(origin, contentType)
            if (mode == ParserMode.REJECT) {
                return@withContext Result.failure(IllegalArgumentException("Unsupported content type"))
            }

            // Initialize config registry with security defaults
            ParserConfigRegistry.initializeDefaults()

            val factory = createDocumentBuilderFactory(mode)
            try {
                val builder = factory.newDocumentBuilder()
                val inputSource = InputSource(StringReader(xmlBody))
                val document = builder.parse(inputSource)
                val root = document.documentElement
                val result = mutableMapOf<String, String>()
                val nodes = root.childNodes
                for (i in 0 until nodes.length) {
                    val node = nodes.item(i)
                    if (node.nodeType == org.w3c.dom.Node.ELEMENT_NODE) {
                        result[node.nodeName] = node.textContent ?: ""
                    }
                }
                Result.success(result)
            } catch (e: Exception) {
                Result.failure(e)
            }
        }
    }

    private fun createDocumentBuilderFactory(mode: ParserMode): DocumentBuilderFactory {
        val factory = DocumentBuilderFactory.newInstance()

        // Apply registered security features
        val registeredFeatures = ParserConfigRegistry.getFeatures()

        when (mode) {
            ParserMode.TRUSTED -> {
                // Trusted mode: still apply all security features uniformly
                // Even trusted sources must not use external entities
                registeredFeatures.forEach { (uri, value) ->
                    try { factory.setFeature(uri, value) } catch (_: Exception) {}
                }
            }
            ParserMode.RESTRICTED -> {
                // Restricted mode: apply all security features from registry
                registeredFeatures.forEach { (uri, value) ->
                    try { factory.setFeature(uri, value) } catch (_: Exception) {}
                }
            }
            ParserMode.REJECT -> { /* unreachable */ }
        }

        factory.isXIncludeAware = false
        factory.isExpandEntityReferences = false
        return factory
    }
}

// API endpoint handler
class MobileApiController {
    private val xmlService = XmlProcessingService()
    private val secureRandom = SecureRandom()

    suspend fun handleDeviceRegistration(requestBody: String, headers: Map<String, String>): ApiResponse {
        val contentType = headers["content-type"] ?: "application/json"
        val origin = headers["x-origin-service"]

        val result = xmlService.processRequest(requestBody, origin, contentType)
        return result.fold(
            onSuccess = { data ->
                val deviceId = data["deviceId"] ?: return ApiResponse(400, "Missing deviceId")
                val token = generateDeviceToken(deviceId)
                ApiResponse(200, "{\"token\": \"$token\", \"status\": \"registered\"}")
            },
            onFailure = { error ->
                ApiResponse(500, "{\"error\": \"${error.message}\"}")
            }
        )
    }

    private fun generateDeviceToken(deviceId: String): String {
        // Use cryptographically secure random material so tokens are not predictable/forgeable
        val randomBytes = ByteArray(32)
        secureRandom.nextBytes(randomBytes)
        val digest = MessageDigest.getInstance("SHA-256")
        digest.update(deviceId.toByteArray())
        digest.update(randomBytes)
        val hash = digest.digest()
        return hash.joinToString("") { "%02x".format(it) }.take(32)
    }
}

data class ApiResponse(val statusCode: Int, val body: String)

// Application bootstrap
suspend fun main() {
    val controller = MobileApiController()

    // Simulate incoming request
    val xmlPayload = """<?xml version="1.0"?><device><deviceId>abc123</deviceId><platform>android</platform></device>"""
    val headers = mapOf("content-type" to "application/xml", "x-origin-service" to "mobile-app")

    val response = controller.handleDeviceRegistration(xmlPayload, headers)
    println("Response: ${response.statusCode} - ${response.body}")
}
